from itertools import combinations, product
import heapq


def _ledger(sequence_first, discounted):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if sequence_first:
                key = (sequence, event.get("revision", 0), pos)
            else:
                key = (event.get("revision", 0), pos)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(numerator):
            if mode == "half_up":
                return (numerator + 5000) // 10000
            return numerator // 10000

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0))
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([-1] + versions)

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector) if version != -1}
        if any(name not in selected or selected[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in selected.items()):
            continue
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue

        closure = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            if name not in selected:
                valid = False
                break
            row = rows[name][selected[name]]
            active_deps = [dep for dep in row.get("deps", [])
                           if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active_deps:
                other = dep["name"]
                if (other not in selected or
                        not dep["min"] <= selected[other] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or closure != set(selected):
            continue

        visiting, finished = set(), set()

        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in closure):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    initial_state = (source, initial_mask, coupons)
    distances = {initial_state: data["start"]}
    queue = [(data["start"], source, initial_mask, coupons)]

    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, left - 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_left))
    return {"arrival": None}


SOLVERS = {
    "component_01": _ledger(True, True),
    "component_02": _ledger(False, False),
    "component_03": _ledger(True, False),
    "component_04": _ledger(False, True),
    "component_05": _ledger(True, True),
