def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    rows = {
        name: {row["version"]: row for row in packages[name]}
        for name in names
    }
    choices = [[-1] + sorted(rows[name]) for name in names]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    # Product order is the lexicographic version-vector order, with -1
    # representing absence. The first feasible vector is therefore optimal.
    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(version in blocked.get(name, [])
               for name, version in selected.items()):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue
        if any(name not in selected or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        closure = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            if name not in selected:
                valid = False
                break
            row = rows[name][selected[name]]
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or
                      dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                if (other not in selected or
                        not dep["min"] <= selected[other] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)

        if not valid or closure != set(selected):
            continue

        visiting, finished = set(), set()

        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in closure):
            continue
        return {"versions": selected}

    return {"error": "unsatisfiable"}


